algorithms.pseudocode:
getOrLoad(k):
  v = GET k
  if v: return v
  token = rand()
  if SET lease:{k} token NX PX 3000:
     val = loader(k)                     # read DB
     # write only if our lease still exists (no DEL happened)
     EVAL 'if GET lease:{k}==token then SET k val EX ttl+jitter; DEL lease:{k}'
     return val
  else:
     sleep(20ms); v = GET k  (retry up to 5x)
     return v or stale(k) or loader_with_db_limit(k)
on invalidate(k): DEL k; DEL lease:{k}
